SELECT complaint_time AS complaintTime, dept_name AS deptName, person_name AS personName, position, category, result, remark FROM TR_SVC_QUALITY_CMPL WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
ORDER BY complaint_time DESC

SELECT praise_time AS praiseTime, dept_name AS deptName, person_name AS personName, position, method, feedback, remark FROM TR_SVC_QUALITY_PRZ WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
ORDER BY praise_time DESC
